  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.inspection-result__title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.inspection-result__indicator {
  flex: 0 0 auto;
