  background: var(--primary);
}

.inspection-result[data-has-failure="true"] .inspection-result__indicator {
  background: var(--destructive, #d93025);
}

.inspection-result__title {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.4;
}

.inspection-result__target {
  min-width: 0;
  max-width: 100%;
  padding: 1px 8px;
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--muted-foreground, var(--foreground));
  font-size: 12px;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.inspection-result__summary {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
}

.inspection-result__chip {
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.inspection-result__chip[data-tone="passed"] {
  background: color-mix(in srgb, var(--muted) 70%, transparent);
  color: var(--muted-foreground, var(--foreground));
}

.inspection-result__chip[data-tone="failed"] {
  background: color-mix(in srgb, var(--destructive, #d93025) 14%, transparent);
  color: var(--destructive, #d93025);
  font-weight: 600;
}

.inspection-result__failed-list,
.inspection-result__passed-list {
  display: flex;
  flex-direction: column;
