  margin: 0;
  padding: 0;
  list-style: none;
  min-width: 0;
}

.inspection-result__failed-item {
  min-width: 0;
  border: 1px solid color-mix(in srgb, var(--destructive, #d93025) 32%, var(--border));
  border-radius: 10px;
  background: color-mix(in srgb, var(--destructive, #d93025) 6%, transparent);
  overflow: hidden;
}

.inspection-result__failed-toggle {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
  padding: 8px 10px;
  border: 0;
  background: none;
  color: var(--foreground);
  font: inherit;
  font-weight: 600;
  text-align: start;
  cursor: pointer;
}

.inspection-result__failed-toggle[data-static="true"] {
  cursor: default;
}

.inspection-result__failed-toggle:focus-visible {
  outline: 2px solid var(--ring, var(--primary));
  outline-offset: -2px;
}

.inspection-result__failed-mark {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border-radius: 999px;
  background: var(--destructive, #d93025);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
}

.inspection-result__failed-name {
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.inspection-result__failed-code {
  min-width: 0;
  padding: 1px 6px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--destructive, #d93025) 14%, transparent);
  color: var(--destructive, #d93025);
  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-size: 11px;
  font-weight: 600;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.inspection-result__chevron {
  flex: 0 0 auto;
  margin-inline-start: auto;
  width: 8px;
  height: 8px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
  transition: transform 120ms ease;
}

.inspection-result__chevron[data-expanded="true"] {
  transform: rotate(225deg);
}

.inspection-result__detail {
  display: flex;
  flex-direction: column;
