}

.inspection-result__detail-list dd {
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.inspection-result__detail-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.inspection-result__copy {
  padding: 3px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--background);
  color: var(--foreground);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.inspection-result__copy:hover {
  border-color: var(--primary);
}

.inspection-result__copy:focus-visible {
  outline: 2px solid var(--ring, var(--primary));
  outline-offset: 1px;
}

.inspection-result__copy-status {
  font-size: 12px;
  color: var(--muted-foreground, var(--foreground));
  overflow-wrap: anywhere;
}

.inspection-result__passed-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  color: var(--muted-foreground, var(--foreground));
  font-size: 12px;
}

.inspection-result__passed-mark {
  flex: 0 0 auto;
  color: var(--primary);
  font-size: 11px;
}

.inspection-result__passed-item[data-tone="other"] .inspection-result__passed-mark {
  color: var(--muted-foreground, var(--foreground));
}

.inspection-result__passed-name {
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.inspection-result__status-raw {
  padding: 0 6px;
  border: 1px solid var(--border);
  border-radius: 999px;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
